import pg from 'pg';
import {AIMessage} from '@langchain/core/messages';
import {SqliteAgentDefinitions,createConfiguredAgentRun} from '../../dist/index.js';
import {PostgresAgentRunLifecycleFoundation} from '../../dist/postgres-run-lifecycle-foundation.js';
import {PostgresAgentActionJournalFoundation} from '../../dist/postgres-action-journal-foundation.js';
import {PostgresAgentTokenBudgetFoundation} from '../../dist/postgres-token-budget-foundation.js';
import {PostgresAgentCheckpointerFoundation} from '../../dist/postgres-checkpointer-foundation.js';
import {PostgresAgentWorkerFoundation} from '../../dist/postgres-worker-foundation.js';
const pool=new pg.Pool({connectionString:process.env.APP_MIXER_TEST_POSTGRES_URL,options:`-c search_path=${process.env.TEST_SCHEMA}`}),scope={tenantId:'tenant',agentId:'agent'},runId=process.env.TEST_RUN_ID;
const transaction=async operation=>{const client=await pool.connect();try{await client.query('BEGIN');const value=await operation((sql,args)=>client.query(sql,args));await client.query('COMMIT');return value;}catch(error){await client.query('ROLLBACK');throw error;}finally{client.release();}};
const config={query:(sql,args)=>pool.query(sql,args),transaction},runs=new PostgresAgentRunLifecycleFoundation(config),definitions=new SqliteAgentDefinitions(':memory:');
definitions.save('tenant',{manifestVersion:1,tenantId:'tenant',agentId:'agent',name:'Agent',owner:{kind:'organization',id:'org'},administrators:['admin'],servicePrincipalId:'service',model:{provider:'local',model:'test'},allowedCapabilities:['send'],lifecycle:{enabled:true,maxAttempts:3,runTimeoutMs:60000},quotas:{maxConcurrentRuns:1,maxTokensPerRun:100,maxRunsPerDay:10}},0);
try{
 const worker=new PostgresAgentWorkerFoundation({runs,definitions,workerId:'replacement-pod',leaseMs:30000,pollMs:1000,authorizeStart:()=>true,execute:async(run,context)=>{const bound={...config,scope,runId,leaseToken:run.leaseToken},journal=new PostgresAgentActionJournalFoundation(bound),budget=new PostgresAgentTokenBudgetFoundation({...bound,maxTokens:100}),saver=new PostgresAgentCheckpointerFoundation(bound),configured=await createConfiguredAgentRun({definitions,tenantId:'tenant',agentId:'agent',expectedVersion:1,bindings:[{operationId:'send',toolName:'send',description:'Send'}],registry:{invoke:async()=>{throw Error('External effect replayed');}},authorizeRun:()=>true,authorizeCapability:()=>true,createModel:()=>({invoke:async()=>{throw Error('unlimited call');},invokeLimited:async history=>{if(!history.some(message=>message._getType()==='tool'))throw Error('Missing checkpointed tool result');return {message:new AIMessage('Done'),usedTokens:10};}}),actionJournal:{journal,maxAttempts:3,prepareInput:(_op,input,key)=>({...input,key})},tokenBudget:{budget,maxTokensPerCall:40},checkpoint:{saver,threadId:runId,resume:true},sharedRunLease:run.leaseToken});let last;for await(const event of configured.run({threadId:'thread',runId,messages:[{role:'user',content:'ignored'}]},{signal:context.signal}))last=event;return last?.type==='RUN_FINISHED'?'succeeded':'uncertain';}});
 const run=await worker.runOnce(scope,runId);if(run.status!=='succeeded')throw Error(`Replacement did not complete: ${run.status}`);console.log('replacement succeeded');
}catch(error){console.error(error);process.exitCode=1;}finally{definitions.close();await pool.end();}
